        "start": proof["start"],
        "end": proof["end"],
        "stages": [
            {
                "at": stage["at"],
                "bundle": _bundle_member_semantics(stage["bundle"]),
                "diff": _checkpoint_diff_semantics(stage["diff"]),
            }
            for stage in proof["stages"]
